contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking inputs: whether caller is admin and a description
    function run(bool makeAdmin, string calldata description) public payable {
        // Ensure this contract has enough ETH if needed (no ETH used here, but kept per template)
        // Set up admin status by calling the public mapping isAdmin through the C interface is not possible to set directly,
        // but C exposes a public mapping isAdmin; however only external transactions can set it in real system.
        // We attempt to set it by calling a function on c that exists in the referenced C contract
        // Since C has no setter, we mimic admin vs non-admin by relying on the initial deployment: the checker deploys a fresh C
        // However we can try to toggle by calling c.isAdmin(address(this)) to observe admin status before call.

        // Read current admin status of this contract
        bool beforeIsAdmin = c.isAdmin(address(this));

        // Perform the operation and capture whether it reverted.
        bool reverted;
        address oracleAddress = address(0);
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, the NewEmergencyOracle event should have been emitted with a non-zero newOracle.
        // We cannot read events, but we can observe that if successful, the newly created EmergencyOracle contract address
        // is non-zero because C.newEmergencyOracle constructs a contract and returns its address only via the event.
        // However we can detect side-effects: the address of a freshly created contract will have non-zero code size.
        // To remain within allowed observations, we assert a relation between beforeIsAdmin and reverted: if caller was admin,
        // the call must not revert; if not admin, it must revert.
        // This is a general property of onlyAdmin modifier on newEmergencyOracle.

        assert(reverted == (!beforeIsAdmin));
    }

    receive() external payable {}
}
